 FOR p IN SELECT * FROM (SELECT key AS prefix,value AS abbreviation FROM jsonb_each_text(types) UNION SELECT value,value FROM jsonb_each_text(types)) prefixes ORDER BY length(prefix) DESC LOOP
 next_char:=substring(n,length(p.prefix)+1,1);
 IF left(lower(n),length(p.prefix))=lower(p.prefix) AND (length(n)=length(p.prefix) OR strpos(U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000',next_char)>0 OR (right(p.prefix,1)='.' AND next_char ~ '[[:alpha:]]')) THEN
 a:=p.abbreviation;rest:=project2_strip(substring(n,length(p.prefix)+1));
 LOOP
 next_char:=substring(rest,length(a)+1,1);
 EXIT WHEN NOT (left(lower(rest),length(a))=lower(a) AND (length(rest)=length(a) OR strpos(U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000',next_char)>0 OR (right(a,1)='.' AND next_char ~ '[[:alpha:]]')));
 rest:=project2_strip(substring(rest,length(a)+1));
 END LOOP;
 RETURN concat_ws(' ',a,nullif(rest,''));END IF;END LOOP;
 IF kind<>'' AND (project2_norm(n)=project2_norm(kind) OR starts_with(project2_norm(n),project2_norm(kind)||' ')) THEN RETURN n;END IF;
 RETURN concat_ws(' ',nullif(coalesce(types->>project2_norm(kind),kind),''),n);
END $$;
CREATE FUNCTION formatted_address(VARIADIC a text[]) RETURNS text IMMUTABLE LANGUAGE plpgsql AS $$
DECLARE country text:=project2_strip(coalesce(a[1],''));region text:=project2_strip(coalesce(a[2],''));district text:=project2_strip(coalesce(a[3],''));community text:=project2_strip(coalesce(a[4],''));settlement text:=project2_strip(coalesce(a[5],''));st text:=project2_strip(coalesce(a[6],''));street text:=project2_strip(coalesce(a[7],''));sty text:=project2_strip(coalesce(a[8],''));base text;special text;ua boolean;parts text[];i integer;
BEGIN
 base:=regexp_replace(project2_norm(region),' (область|обл\.)$','');special:=regexp_replace(project2_norm(region),'^м\. *','');
 ua:=project2_norm(country) IN ('україна','украина','ukraine','ua','ukr') OR (country='' AND (base IN ('волинська','вінницька','дніпропетровська','донецька','житомирська','закарпатська','запорізька','київська','кіровоградська','луганська','львівська','миколаївська','одеська','полтавська','рівненська','сумська','тернопільська','харківська','херсонська','хмельницька','черкаська','чернівецька','чернігівська','івано-франківська') OR special IN ('київ','севастополь','ар крим','арк','автономна республіка крим','крим')));
 IF ua THEN
 IF special NOT IN ('київ','севастополь','ар крим','арк','автономна республіка крим','крим') AND (base IN ('волинська','вінницька','дніпропетровська','донецька','житомирська','закарпатська','запорізька','київська','кіровоградська','луганська','львівська','миколаївська','одеська','полтавська','рівненська','сумська','тернопільська','харківська','херсонська','хмельницька','черкаська','чернівецька','чернігівська','івано-франківська') OR region ~* ' (область|обл\.)$') THEN region:=regexp_replace(region,'(['||U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'||']+(область|обл\.))+$','','i')||' обл.';
 ELSIF special IN ('київ','севастополь') AND regexp_replace(project2_norm(settlement),'^м\. *','')=special THEN region:=''; END IF;
 IF district<>'' THEN district:=regexp_replace(district,'(['||U&'\0009\000A\000B\000C\000D\001C\001D\001E\001F\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'||']+(район|р-н))+$','','i')||' р-н'; END IF; END IF;
 IF settlement<>'' THEN community:=''; END IF;
 st:=coalesce(('{"city": "місто", "special_city": "місто", "village": "село", "settlement": "селище"}'::jsonb)->>project2_norm(st),st);
 parts:=ARRAY[country,region,district,community,project2_typed(st,settlement,'{"місто": "м.", "село": "с.", "селище": "с-ще", "селище міського типу": "смт", "хутір": "х.", "смт.": "смт"}'::jsonb),project2_typed(sty,street,'{"вулиця": "вул.", "проспект": "просп.", "провулок": "пров.", "бульвар": "бульв.", "площа": "пл.", "проїзд": "пр-д", "узвіз": "узвіз", "набережна": "наб.", "шосе": "шосе", "алея": "алея", "тупик": "туп."}'::jsonb)];
 FOR i IN 9..13 LOOP IF project2_strip(coalesce(a[i],''))<>'' THEN parts:=array_append(parts,(ARRAY['буд.','корп.','будівля','кв.','кімн.'])[i-8]||' '||project2_strip(a[i])); END IF; END LOOP;
 parts:=parts||ARRAY[project2_strip(coalesce(a[14],'')),project2_strip(coalesce(a[15],''))];
 RETURN array_to_string(array_remove(parts,''),', '); END $$;
CREATE FUNCTION project2_date_match(d integer,m integer,y integer,encoded text,partial boolean,lo integer,hi integer) RETURNS integer IMMUTABLE LANGUAGE plpgsql AS $$
DECLARE spec jsonb:=encoded::jsonb;lower_date date:=greatest(coalesce(nullif(spec->>'start','')::date,DATE '0001-01-01'),make_date(lo,1,1));upper_date date:=least(coalesce(nullif(spec->>'end','')::date,DATE '9999-12-31'),make_date(hi,12,31));cy integer;cm integer;cd integer;candidate date;
BEGIN
 IF NOT project2_components(d,m,y,partial) OR (NOT partial AND num_nonnulls(d,m,y)<3) OR (coalesce((spec->>'incomplete_only')::boolean,false) AND num_nonnulls(d,m,y)=3) OR lower_date>upper_date THEN RETURN 0; END IF;
 FOR cy IN greatest(coalesce(y,extract(year FROM lower_date)::integer),lo)..least(coalesce(y,extract(year FROM upper_date)::integer),hi) LOOP
 IF jsonb_array_length(spec->'years')>0 AND NOT (spec->'years' @> to_jsonb(ARRAY[cy])) THEN CONTINUE; END IF;
 FOR cm IN coalesce(m,1)..coalesce(m,12) LOOP
 IF jsonb_array_length(spec->'months')>0 AND NOT (spec->'months' @> to_jsonb(ARRAY[cm])) THEN CONTINUE; END IF;
 FOR cd IN coalesce(d,1)..coalesce(d,31) LOOP
 IF jsonb_array_length(spec->'days')>0 AND NOT (spec->'days' @> to_jsonb(ARRAY[cd])) THEN CONTINUE; END IF;
 BEGIN candidate:=make_date(cy,cm,cd);EXCEPTION WHEN datetime_field_overflow THEN CONTINUE;END;
 IF candidate BETWEEN lower_date AND upper_date THEN RETURN 1; END IF;
 END LOOP; END LOOP; END LOOP; RETURN 0;END $$;
